entries[146304] = { ["name"] = "Hammer des Teufelstitanen", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nVerkaufspreis:" }
entries[146305] = { ["name"] = "Grüne Wintermütze", ["text"] = "Wird beim Aufheben gebunden\nKopf\nBenötigt Winterhauchfest\nVerkaufspreis:" }
entries[146308] = { ["name"] = "Fass Sturmgebräu", ["text"] = "Questgegenstand\n\"Tödlich gegen Dämonen!\"" }
entries[146309] = { ["name"] = "Ausgezehrte Zauberreagenzien", ["text"] = "Wird beim Aufheben gebunden\n\"Die vertrockneten Überreste eines erfolgreich gewirkten Zaubers der Hochgeborenen.\"\nVerkaufspreis:" }
entries[146310] = { ["name"] = "Phiole mit flüssiger Teufelsflamme", ["text"] = "Questgegenstand\nEinzigartig\n\"Von kaum eingedämmter Teufelsenergie getrübt.\"" }
entries[146311] = { ["name"] = "Fläschchen mit Teufelsblut", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Blut in dem Gefäß kocht vor Zorn.\"" }
entries[146312] = { ["name"] = "Dämonische Asche", ["text"] = "Questgegenstand\nEinzigartig\n\"Leuchtet schwach vor Teufelsenergie.\"" }
entries[146313] = { ["name"] = "Tonscherben der Hochgeborenen", ["text"] = "Wird beim Aufheben gebunden\n\"Der blaue Ton wurde mit rosenrotem Pigment bemalt.\"\nVerkaufspreis:" }
entries[146314] = { ["name"] = "Marmorne Pfeilspitze", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Pfeilspitze gehörte wahrscheinlich einer Schildwache der alten Hochgeborenen.\"\nVerkaufspreis:" }
entries[146315] = { ["name"] = "Mondrune von Elune", ["text"] = "Wird beim Aufheben gebunden\n\"Der importune Verlust dieser Rune in einer Lagune bedrückte die ganze Kommune.\"\nVerkaufspreis:" }
entries[146316] = { ["name"] = "Uraltes Tafelsilber aus Suramar", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Art Münze wird in Suramar seit mindestens 7000 Jahren nicht mehr verwendet.\"\nVerkaufspreis:" }
