entries[146401] = { ["name"] = "Kurierendes Gebräu", ["text"] = "Questgegenstand\nEinzigartig\n\"Riecht ranzig und schmeckt noch viel schlechter.\"" }
entries[146402] = { ["name"] = "Ernos Enigma", ["text"] = "Questgegenstand\n\"Einfach zu erlernen, schwer zu meistern.\"" }
entries[146403] = { ["name"] = "Zwielichtapparat", ["text"] = "Questgegenstand\n\"Fäden aus dunkler Energie durchziehen das Innere des Apparats und wirbeln darin herum.\"" }
entries[146404] = { ["name"] = "Diadem der Lu'minellia", ["text"] = "Questgegenstand\n\"Getragen von den hochelfischen Königen vergangener Zeitalter.\"" }
entries[146405] = { ["name"] = "Kristallisierte Silithidenessenz", ["text"] = "Questgegenstand\n\"Erschaffen aus dem Blut von eintausend Silithidenmagi.\"" }
entries[146406] = { ["name"] = "Vantusrune: Das Grabmal des Sargeras", ["text"] = "Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:" }
entries[146407] = { ["name"] = "Abgenutztes Schmuckstück", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Obwohl dieser Messingkompass bessere Tage gesehen hat, war das handwerkliche Können seiner Herstellung eindeutig höchsten Ranges.\"" }
entries[146408] = { ["name"] = "Abgenutztes Schmuckstück", ["text"] = "Questgegenstand\n\"Obwohl dieser Messingkompass bessere Tage gesehen hat, war das handwerkliche Können seiner Herstellung eindeutig höchsten Ranges.\"" }
entries[146409] = { ["name"] = "Seelenstein der Nachtgeborenen", ["text"] = "Questgegenstand\n\"Pulsiert vor Kathra'natirs zurückgehaltenem Zorn.\"" }
entries[146411] = { ["name"] = "Vantusrunentechnik: Das Grabmal des Sargeras", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung der Vantusrune: Das Grabmal des Sargeras.\nErschafft eine Vantusrune: Das Grabmal des Sargeras.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Das Grabmal des Sargeras\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (10), Rosenrote Pigmente (30)" }
entries[146412] = { ["name"] = "Vantusrunentechnik: Das Grabmal des Sargeras", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Das Grabmal des Sargeras effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Das Grabmal des Sargeras.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Das Grabmal des Sargeras\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (8), Rosenrote Pigmente (30)" }
entries[146413] = { ["name"] = "Vantusrunentechnik: Das Grabmal des Sargeras", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Das Grabmal des Sargeras effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung einer Vantusrune: Das Grabmal des Sargeras.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nVantusrune: Das Grabmal des Sargeras\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Grabmal des Sargeras ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Fahle Pigmente (6), Rosenrote Pigmente (30)" }
