entries[146666] = { ["name"] = "Celumbra, Dichotomie der Nacht", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nSchulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 120 / 120\nKlassen: Priester , Magier , Hexenmeister\nAnlegen: Wenn sich ein Gegner innerhalb von 12 Metern um Euch befindet, werdet Ihr in Schatten gehüllt, die Euren erlittenen Schaden um 5% verringern und Eure Bewegungsgeschwindigkeit um 10% erhöhen. Wenn sich keine Gegner innerhalb von 12 Metern um Euch befinden, heilt Euch Celumbras Sternenlicht alle 1 Sek. um 1% Eurer maximalen Gesundheit.\n\"Schatten und Sterne, Dunkelheit und Licht, Verzweiflung und Hoffnung.\"\nVerkaufspreis:" }
entries[146667] = { ["name"] = "Rethus unerschöpflicher Mut", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nTaille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 4.\nErhöht Eure Meisterschaftswertung um + 3.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Krieger , Paladin , Todesritter\nAnlegen: Wenn sich ein Gegner innerhalb von 8 Metern von Euch befindet, werdet Ihr alle 3 Sek. um 2% Eurer maximalen Gesundheit geheilt. Wenn sich keine Gegner innerhalb von 8 Metern von Euch befinden, wird Eure Bewegungsgeschwindigkeit um 15% erhöht.\n\"Sein Mut wirkte ansteckend.\"\nVerkaufspreis:" }
entries[146668] = { ["name"] = "Träger der Weisheit", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Jäger , Schamane , Rufer\nAnlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in eine Geistereule, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n\"Selbst nach dem Tod wachen die Geister der Eulen noch über ihre Meister, solange ein sicher geführter Handschuh sie trägt.\"\nVerkaufspreis:" }
entries[146669] = { ["name"] = "Ewiges Refugium der Schildwache", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nFüße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\n\nPrismatischer Sockel\nPrismatischer Sockel\nPrismatischer Sockel\n\nHaltbarkeit 95 / 95\nKlassen: Schurke , Mönch , Druide , Dämonenjäger\nAnlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in einen Irrwisch, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n\"Ihr Geist erfüllt das Leder dieser Stiefel und wird so an diese Welt gebunden.\"\nVerkaufspreis:" }
