entries[147002] = { ["name"] = "Talisman der steigenden Flut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nBenutzen: Während Ihr stillsteht, erhöht sich Euer Tempo alle 1 Sek. um 3 . Dieser Effekt ist bis zu 10-mal stapelbar. Hält 20 Sek. lang an. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147003] = { ["name"] = "Barbarischer Gedankenknechter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heileffekte haben eine Chance, zusätzlich 45 Heilung hervorzurufen. Dieser Effekt tritt häufiger auf, je niedriger Euer Mana ist.\nVerkaufspreis:" }
entries[147004] = { ["name"] = "Meeresstern der Tiefenmutter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Euer Gruppenheilzauber hat eine Chance, Euch 'Umarmung des Ozeans' zu gewähren, wodurch Euer nächster verletzter Verbündeter innerhalb von 15 Metern 8 Sek. lang alle 0.25 Sek. um 7 Gesundheit geheilt wird. Gilt für Heilerspezialisierungen.\nVerkaufspreis:" }
entries[147005] = { ["name"] = "Kelch des Mondlichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 Intelligenz\nAnlegen: Eure Heilzauber haben eine Chance, Euren kritischen Trefferwert oder Euer Tempo für 12 Sek. um 22 zu erhöhen. Dieser Effekt gewährt tagsüber kritischen Trefferwert und nachts Tempo.\nVerkaufspreis:" }
entries[147006] = { ["name"] = "Archiv des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nBenutzen: Kanalisiert eine läuternde Matrix in einen Verbündeten, die ihn im Verlauf von 3 Sek. um 439 Gesundheit heilt. Wenn die Kanalisierung vollständig abgeschlossen wird, erhält das Ziel zusätzlich für 10 Sek. einen Schild, der 160 Schaden verhindert. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[147007] = { ["name"] = "Des Betrügers großer Plan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Markiert einen verbündeten Spielercharakter mit 'Leitende Hand' und heilt ihn so 2 Min. lang alle 3.0 Sek. um 22 Gesundheit. Falls seine Gesundheit unter 35% fällt, wird 'Leitende Hand' aufgezehrt und gewährt ihm einen Schild, der 15 Sek. lang [(1 + Vielseitigkeit) * 379 ] Schaden verhindert (2 Min. Wiederaufladezeit, 2 Aufladungen).\nVerkaufspreis:" }
entries[147009] = { ["name"] = "Höllenasche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Nahkampfangriffe haben eine Chance, zusätzlich 20 Feuerschaden zu verursachen. Die kritische Trefferchance dieses Schadens wird für jeden Verbündeten innerhalb von 10 Metern, der diesen Gegenstand trägt, um 10% erhöht.\nVerkaufspreis:" }
entries[147010] = { ["name"] = "Wiege des Kummers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nAnlegen: Solange Ihr bei mehr als 80% Gesundheit seid, erhaltet Ihr je nach Spezialisierung 1 Stärke oder Beweglichkeit pro Sekunde. Dieser Effekt ist bis zu 10-mal stapelbar. Wenn Eure Gesundheit unter 50% fällt, endet dieser Effekt.\nVerkaufspreis:" }
entries[147011] = { ["name"] = "Phiole des unablässigen Toxins", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nBenutzen: Fügt einem Gegner in Nahkampfreichweite 56 Schattenschaden sowie zusätzlich im Verlauf von 20 Sek. 91 Schaden zu. Wenn der Gegner stirbt, während der Effekt aktiv ist, wird die Abklingzeit dieser Fähigkeit um 45 Sek. verringert. (1 Min Abklingzeit)\n\"Diese toxischen Wellen ebben niemals ab.\"\nVerkaufspreis:" }
entries[147012] = { ["name"] = "Umbralmondgleven", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nBenutzen: Erschafft einen Glevensturm an Eurer Position, der Gegnern in der Nähe alle 1 Sek. 18 Arkanschaden zufügt. Nach 8 Sek. zerbersten die Gleven und fügen Gegnern im Effektbereich zusätzlich 49 Arkanschaden zu. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147013] = { ["name"] = "Kette aus gezogenen Schneidezähnen", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure Tempowertung um + 8.\n+ 6 Vielseitigkeit\nVerkaufspreis:" }
entries[147014] = { ["name"] = "Medaillon der zersplitterten Seelen", ["text"] = "Wird beim Aufheben gebunden\nHals\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\nErhöht Eure Meisterschaftswertung um + 8.\nVerkaufspreis:" }
entries[147015] = { ["name"] = "Auslöschungsmaschine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure automatischen Angriffe haben eine Chance, je nach Spezialisierung Eure Stärke oder Beweglichkeit 12 Sek. lang um 12 zu erhöhen und Kugeln aus Teufelsenergie auszustoßen. Wenn Ihr eine Kugel einsammelt, wird die Dauer dieses Effekts um 3 Sek. verlängert. (12s Abklingzeit)\nVerkaufspreis:" }
entries[147016] = { ["name"] = "Schrecken aus der Tiefe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 7.\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, ein Ungetüm aus der Tiefe zu beschwören, das Euer Ziel in einem Stück verschlingt und so 182 Naturschaden verursacht, der auf Euch und alle Gegner in der Nähe aufgeteilt wird. (5s Abklingzeit)\nVerkaufspreis:" }
entries[147017] = { ["name"] = "Angelaufenes Schildwachenmedaillon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nBenutzen: Ruft eine Spektraleule herbei, die Euer Ziel angreift und ihm 20 Sek. lang alle 1 Sek. 15 Arkanschaden zufügt. Eure Distanzangriffe und Zauber gegen diesen Gegner gewähren eine Chance, dass die Eule einen zusätzlichen Angriff ausführt, der 19 Schaden verursacht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[147018] = { ["name"] = "Spektrales Weihrauchfass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Eure Distanzangriffe und Zauber haben eine Chance, einen Speer der Pein zu erschaffen. Nach 3 Sek. wird der Speer in Richtung Eures Ziels abgefeuert und fügt allen Gegnern auf seinem Weg 73 Schattenschaden zu. (5s Abklingzeit)\nVerkaufspreis:" }
entries[147019] = { ["name"] = "Foliant des zerrinnenden Verstands", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Intelligenz]\nBenutzen: Verursacht im Verlauf von 12 Sek. 71 Schattenschaden. Wenn dieser Effekt endet oder das Ziel stirbt, gewinnt Ihr für 12 Sek. plus der verbleibenden Zeit des Effekts 2 kritische Trefferchance hinzu. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[147020] = { ["name"] = "Schuppenband der Knechtschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\nErhöht Eure Tempowertung um + 6.\nErhöht Eure Meisterschaftswertung um + 8.\nVerkaufspreis:" }
