entries[147022] = { ["name"] = "Fiebriger Rückenpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+5 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Eure Rüstung um 20 erhöht wird und Ihr 6 Schaden als Feuerschaden reflektiert, wenn Ihr angegriffen werdet. Hält 10 Sek. lang an.\nVerkaufspreis:" }
entries[147023] = { ["name"] = "Hunger des Leviathans", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 7.\nBenutzen: Entfesselt verschlingende Finsternis gegen einen Gegner, was seine Bewegungsgeschwindigkeit um 70% verringert und ihm im Verlauf von 8 Sek. 134 Schattenschaden zufügt. Ihr werdet um 300% des verursachten Schadens geheilt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147024] = { ["name"] = "Reliquiar der Verdammten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Ausdauer\nBenutzen: Umgibt Euch mit klagenden Seelen, um 10 Sek. lang 50% des erlittenen Schadens zu verhindern, bis Ihr insgesamt [ 585 * (1 + Vielseitigkeit)] Schaden verhindert habt. Basierend auf der absorbierten Schadensmenge wird die Abklingzeit dieser Fähigkeit um bis zu 30 Sek. verringert. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[147025] = { ["name"] = "Rekonfiguriertes Wächtermodul", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr im Verlauf von 6 Sek. um 72 Gesundheit geheilt werdet. Wenn dieser Effekt abläuft, erhalten Ihr und bis zu 4 Verbündete innerhalb von 15 Metern einen Schild, der 15 Sek. lang 21 Schaden verhindert. (7s Abklingzeit)\nVerkaufspreis:" }
entries[147026] = { ["name"] = "Unbeständiger kosmischer Splitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr 'Verschlagenheit des Betrügers' erhaltet. Dieser Effekt ist bis zu 10-mal stapelbar.\nBenutzen: Verbraucht Eure Verschlagenheit, um die Abklingzeit von einer mächtigen Defensivfähigkeit um 10 Sek. pro Stapel zu verringern. Falls eine mächtige Defensivfähigkeit aktuell aktiv ist, wird stattdessen die Dauer der Fähigkeit um 1 Sek. pro Stapel verlängert. Gilt für Tankspezialisierungen. (20 Sek. Abklingzeit)\nVerkaufspreis:" }
