entries[147120] = { ["name"] = "Technik: Grimoire des Schattensukkubus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Grimoire des Schattensukkubus herstellt.\nStellt ein Grimoire des Schattensukkubus her.\nBenötigt Inschriftenkunde der Verheerten Inseln (1)\nVerkaufspreis:\nGrimoire des Schattensukkubus\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Schattensukkubus beim Barbier frei.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Fahle Pigmente (15), Rosenrote Pigmente (5)" }
entries[147121] = { ["name"] = "Brustplatte des Grabwärters", ["text"] = "Wird beim Aufheben gebunden\nBrust Platte\n18 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 165 / 165\nKlassen: Todesritter\nRüstung des Grabwärters (0/6)\nBrustplatte des Grabwärters\nUmhang des Grabwärters\nHandschützer des Grabwärters\nMaske des Grabwärters\nBeinplatten des Grabwärters\nSchulterstücke des Grabwärters\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Siedeblut' gewährt Euch für 10 Sek. 'Grabwärter'. Dieser Effekt erhöht Eure Vielseitigkeit um 88 . (100ms Abklingzeit)\n(2) Set Frost: Während 'Säule des Frosts' aktiv ist, wird dessen Effektdauer pro 60 verbrauchter Runenmacht um 1.0 Sek. erhöht.\n(2) Set Unheilig: Jeder von Eurer 'Armee der Toten' beschworene Ghul erhöht Euren Schaden für 3 Sek. um 15%. Jeder Ghul verlängert die Dauer des Effekts; der Effekt ist nicht stapelbar.\n(4) Set Blut: Während 'Grabwärter' aktiv ist, sind die Kosten Eurer Fähigkeit 'Todesstoß' um 5 Runenmacht verringert.\n(4) Set Frost: Erhöht pro 3 verbrauchten Runen den Stärkebonus Eures nächsten Einsatzes von 'Säule des Frosts' um 1%.\n(4) Set Unheilig: Jede von Euch verbrauchte Rune verringert die Abklingzeit von 'Armee der Toten' um 2.0 Sek.\nVerkaufspreis:" }
entries[147122] = { ["name"] = "Umhang des Grabwärters", ["text"] = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+3 [Beweglichkeit oder Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nKlassen: Todesritter\nRüstung des Grabwärters (0/6)\nBrustplatte des Grabwärters\nUmhang des Grabwärters\nHandschützer des Grabwärters\nMaske des Grabwärters\nBeinplatten des Grabwärters\nSchulterstücke des Grabwärters\nAltes Set: Bonus ist nicht aktiv\n(2) Set Blut: 'Siedeblut' gewährt Euch für 10 Sek. 'Grabwärter'. Dieser Effekt erhöht Eure Vielseitigkeit um 88 . (100ms Abklingzeit)\n(2) Set Frost: Während 'Säule des Frosts' aktiv ist, wird dessen Effektdauer pro 60 verbrauchter Runenmacht um 1.0 Sek. erhöht.\n(2) Set Unheilig: Jeder von Eurer 'Armee der Toten' beschworene Ghul erhöht Euren Schaden für 3 Sek. um 15%. Jeder Ghul verlängert die Dauer des Effekts; der Effekt ist nicht stapelbar.\n(4) Set Blut: Während 'Grabwärter' aktiv ist, sind die Kosten Eurer Fähigkeit 'Todesstoß' um 5 Runenmacht verringert.\n(4) Set Frost: Erhöht pro 3 verbrauchten Runen den Stärkebonus Eures nächsten Einsatzes von 'Säule des Frosts' um 1%.\n(4) Set Unheilig: Jede von Euch verbrauchte Rune verringert die Abklingzeit von 'Armee der Toten' um 2.0 Sek.\nVerkaufspreis:" }
