entries[147132] = { ["name"] = "Schulterpolster des Dämonenbanns", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 100 / 100\nKlassen: Dämonenjäger\nRüstung des Dämonenbanns (0/6)\nHarnisch des Dämonenbanns\nSchleier des Dämonenbanns\nStulpen des Dämonenbanns\nGesichtsschutz des Dämonenbanns\nGamaschen des Dämonenbanns\nSchulterpolster des Dämonenbanns\nAltes Set: Bonus ist nicht aktiv\n(2) Set Verwüstung: Erhöht die kritische Trefferchance von 'Klingentanz' um 20%.\n(2) Set Rachsucht: Nach dem Verschlingen eines Seelenfragments erleidet Ihr 6 Sek. lang 5% weniger Schaden von allen Gegnern innerhalb von 10 Metern.\n(4) Set Verwüstung: Wenn 'Klingentanz' mindestens einen Gegner trifft, erstattet die Fähigkeit 20 Jähzorn zurück.\n(4) Set Rachsucht: 'Seelenspalter' erhöht 8 Sek. lang Eure Vielseitigkeit um 71 .\nVerkaufspreis:" }
entries[147133] = { ["name"] = "Tunika des Sturmherzens", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 165 / 165\nKlassen: Druide\nSturmherzgewandung (0/6)\nTunika des Sturmherzens\nTuch des Sturmherzens\nHandschuhe des Sturmherzens\nKopfputz des Sturmherzens\nBeinschützer des Sturmherzens\nMantelung des Sturmherzens\nAltes Set: Bonus ist nicht aktiv\n(2) Set Gleichgewicht: Erhöht Eure maximale astrale Macht um 30 sowie den kritischen Schaden Eures Zaubers 'Sternensog' um 30%.\n(2) Set Wildheit: Immer wenn 'Zerfetzen' Schaden verursacht, erhaltet Ihr 1 Energie.\n(2) Set Wächter: Die Abklingzeit von 'Rasende Regeneration' wird, basierend auf Eurer aktuellen Gesundheit beim Einsatz, um bis zu 40% verringert. Die Abklingzeit ist umso geringer, je niedriger Eure Gesundheit beim Einsatz ist.\n(2) Set Wiederherstellung: Die Abklingzeit von 'Rasche Heilung' wird, basierend auf der aktuellen Gesundheit Eures Ziels, um bis zu 40% verringert. Die Abklingzeit ist umso geringer, je niedriger die Gesundheit des Ziels beim Einsatz ist.\n(4) Set Gleichgewicht: 'Sternensog' und 'Sternenregen' erhöhen Euer Tempo für 20 Sek. um 2%. Bis zu 4-mal stapelbar. Das Hinzugewinnen eines Stapels setzt die Effektdauer nicht zurück.\n(4) Set Wildheit: 'Zerfetzen' verursacht 10% mehr Schaden und hält 4 Sek. länger an.\n(4) Set Wächter: Verringert die Abklingzeit von 'Rasende Regeneration' pro 20 verbrauchter Wut um 1 Sek.\n(4) Set Wiederherstellung: 'Rasche Heilung' erhöht die Wirksamkeit Eurer durch 'Erblühen' hervorgerufenen Heilung 10 Sek. lang um 200%.\nVerkaufspreis:" }
